-- ============================================================
-- MRGR Color Center — Sales & Inventory System
-- MySQL Database Schema
-- Database: MRGR_ColorCenter
-- ============================================================

CREATE DATABASE IF NOT EXISTS `MRGR_ColorCenter` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `MRGR_ColorCenter`;

-- ------------------------------------------------------------
-- 1. USERS TABLE
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `users` (
    `id` VARCHAR(50) NOT NULL PRIMARY KEY,
    `username` VARCHAR(100) NOT NULL UNIQUE,
    `password` VARCHAR(255) NOT NULL,
    `name` VARCHAR(150) NOT NULL,
    `role` ENUM('admin', 'cashier', 'staff') NOT NULL DEFAULT 'cashier',
    `status` ENUM('active', 'inactive') NOT NULL DEFAULT 'active',
    `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------
-- 2. PRODUCTS TABLE
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `products` (
    `id` VARCHAR(50) NOT NULL PRIMARY KEY,
    `product_id` VARCHAR(50) NULL,
    `name` VARCHAR(200) NOT NULL,
    `product_name` VARCHAR(200) NULL,
    `brand` VARCHAR(100) NOT NULL,
    `type` VARCHAR(100) NOT NULL,
    `category` VARCHAR(100) NULL,
    `color` VARCHAR(100) DEFAULT '-',
    `color_hex` VARCHAR(20) NULL DEFAULT '#FFFFFF',
    `supplier_id` VARCHAR(50) NULL,
    `price` DECIMAL(10,2) NOT NULL DEFAULT 0.00,
    `recent_price` DECIMAL(10,2) NULL DEFAULT NULL,
    `pending_price` DECIMAL(10,2) NULL DEFAULT NULL,
    `price_history` TEXT NULL,
    `stock` DECIMAL(10,2) NOT NULL DEFAULT 0.00,
    `can_stock` TEXT NULL,
    `opened_stock` DECIMAL(10,2) NOT NULL DEFAULT 0.00,
    `opened_can_size` INT NOT NULL DEFAULT 0,
    `opened_by_size` TEXT NULL,
    `sizes` TEXT NULL,
    `pending_sizes` TEXT NULL,
    `pending_edit` TEXT NULL,
    `threshold` DECIMAL(10,2) NOT NULL DEFAULT 5.00,
    `threshold_by_size` TEXT NULL,
    `status` VARCHAR(30) NOT NULL DEFAULT 'active',
    `deactivation_reason` TEXT NULL,
    `deactivated_at` DATETIME NULL,
    `deactivated_by` VARCHAR(150) NULL,
    `updated_by` VARCHAR(150) NULL,
    `discontinue_reason` TEXT NULL,
    `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    `updated_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    KEY `idx_products_product_id` (`product_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------
-- 2B. PRODUCT SIZES TABLE
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `product_sizes` (
    `size_id` VARCHAR(50) NOT NULL PRIMARY KEY,
    `product_id` VARCHAR(50) NOT NULL,
    `container_size` DECIMAL(10,2) NOT NULL,
    `price_per_liter` DECIMAL(10,2) NOT NULL DEFAULT 0.00,
    `price_per_can` DECIMAL(10,2) NOT NULL DEFAULT 0.00,
    `minimum_stock` INT NOT NULL DEFAULT 5,
    `is_active` TINYINT(1) NOT NULL DEFAULT 1,
    `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    `updated_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    UNIQUE KEY `uk_product_size` (`product_id`, `container_size`),
    KEY `idx_ps_product_id` (`product_id`),
    CONSTRAINT `fk_product_sizes_product` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------
-- 2C. INVENTORY TABLE
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `inventory` (
    `inventory_id` VARCHAR(50) NOT NULL PRIMARY KEY,
    `size_id` VARCHAR(50) NOT NULL,
    `sealed_quantity` INT NOT NULL DEFAULT 0,
    `opened_quantity` INT NOT NULL DEFAULT 0,
    `remaining_volume` DECIMAL(10,2) NOT NULL DEFAULT 0.00,
    `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    `updated_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    UNIQUE KEY `uk_inventory_size` (`size_id`),
    CONSTRAINT `fk_inventory_size` FOREIGN KEY (`size_id`) REFERENCES `product_sizes` (`size_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------
-- 3. SUPPLIERS TABLE
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `suppliers` (
    `id` VARCHAR(50) NOT NULL PRIMARY KEY,
    `name` VARCHAR(200) NOT NULL,
    `contact` VARCHAR(150) DEFAULT '',
    `phone` VARCHAR(100) DEFAULT '',
    `email` VARCHAR(150) DEFAULT '',
    `address` VARCHAR(255) DEFAULT '',
    `product_ids` TEXT,
    `status` ENUM('active', 'inactive') NOT NULL DEFAULT 'active',
    `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------
-- 4. SALES TABLE
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `sales` (
    `id` VARCHAR(50) NOT NULL PRIMARY KEY,
    `receipt_no` VARCHAR(50) DEFAULT NULL,
    `date` DATETIME NOT NULL,
    `cashier_name` VARCHAR(150) NOT NULL,
    `subtotal` DECIMAL(10,2) NOT NULL DEFAULT 0.00,
    `total` DECIMAL(10,2) NOT NULL DEFAULT 0.00,
    `status` VARCHAR(50) NOT NULL DEFAULT 'completed',
    `refund_total` DECIMAL(10,2) NOT NULL DEFAULT 0.00,
    `returns_json` LONGTEXT NULL,
    `items_json` LONGTEXT NOT NULL,
    `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------
-- 5. STOCK MOVEMENTS TABLE
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `movements` (
    `id` VARCHAR(50) NOT NULL PRIMARY KEY,
    `date` DATETIME NOT NULL,
    `type` VARCHAR(50) NOT NULL,
    `product_id` VARCHAR(50) NULL,
    `size_id` VARCHAR(50) NULL,
    `container_size` DECIMAL(10,2) NULL,
    `product_name` VARCHAR(200) NOT NULL,
    `qty_change` DECIMAL(10,2) NOT NULL DEFAULT 0.00,
    `staff_name` VARCHAR(150) NOT NULL,
    `note` TEXT,
    `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    KEY `idx_mv_product_id` (`product_id`),
    KEY `idx_mv_size_id` (`size_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------
-- 6. PURCHASE ORDERS TABLE
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `purchase_orders` (
    `id` VARCHAR(50) NOT NULL PRIMARY KEY,
    `po_number` VARCHAR(50) NOT NULL UNIQUE,
    `supplier_id` VARCHAR(50) NOT NULL,
    `supplier_name` VARCHAR(200) NOT NULL,
    `order_date` DATETIME NOT NULL,
    `expected_date` DATE DEFAULT NULL,
    `status` VARCHAR(50) NOT NULL DEFAULT 'ordered',
    `total_amount` DECIMAL(10,2) NOT NULL DEFAULT 0.00,
    `items_json` LONGTEXT NOT NULL,
    `notes` TEXT,
    `created_by` VARCHAR(150) NOT NULL,
    `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    `received_at` DATETIME DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------
-- 7. AUDIT LOGS TABLE
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `audit_logs` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `created_at` DATETIME NOT NULL,
    `user_id` VARCHAR(64) NULL,
    `user_name` VARCHAR(255) NULL,
    `user_role` VARCHAR(32) NULL,
    `action` VARCHAR(64) NOT NULL,
    `entity` VARCHAR(64) NULL,
    `product_id` VARCHAR(64) NULL,
    `details` TEXT NULL,
    `ip_address` VARCHAR(64) NULL,
    INDEX `idx_created` (`created_at`),
    INDEX `idx_action` (`action`),
    INDEX `idx_user` (`user_name`),
    INDEX `idx_product` (`product_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------
-- 7B. ADJUSTMENT REQUESTS TABLE
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `adjustment_requests` (
    `id` VARCHAR(50) NOT NULL PRIMARY KEY,
    `req_number` VARCHAR(50) NOT NULL,
    `date` DATETIME NOT NULL,
    `requested_by` VARCHAR(100) NOT NULL,
    `role` VARCHAR(50) NOT NULL DEFAULT 'staff',
    `status` VARCHAR(50) NOT NULL DEFAULT 'pending',
    `rows_json` LONGTEXT NOT NULL,
    `batch_note` TEXT NULL,
    `reviewed_by` VARCHAR(100) NULL,
    `reviewed_at` DATETIME NULL,
    `reject_reason` TEXT NULL,
    `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    KEY `idx_adj_status` (`status`),
    KEY `idx_adj_req_num` (`req_number`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

